def char_chapters(cell, limit=8):
    """字考案例見於哪些回原文（生態鏈：字考→原文）；按命中字數排序。"""
    chars = re.findall(r"[一-龥]", cell)
    if not chars:
        return "—"
    hits = []
    for n in range(1, len(CH) + 1):
        t = YUANWEN_DATA.get(str(n)) or ""
        if not t:
            continue
        c = sum(1 for ch in chars if ch in t)
        if c:
            hits.append((c, n))
    hits.sort(key=lambda x: x[1])   # 按回號排序（易讀）
    return "、".join(f'<a href="chapters/{n:03d}.html">{n}</a>' for _c, n in hits[:limit]) or "—"

def zikao_table():
    head = ('<table class="acts"><tr><th>字</th><th>粵音／拆解</th><th>破譯</th>'
            '<th>錨位</th><th>見於回目（原文）</th></tr>')
    body = "".join(
        f'<tr><td>{a}　<a class="s" href="yuanwen.html?q={a.split("／")[0][:2]}">原文搜</a></td>'
        f'<td>{b}</td><td>{c}</td><td>{d}</td><td>{char_chapters(a)}</td></tr>'
        for a, b, c, d in ZIKAO_ROWS)
    return head + body + "</table>"

def poem_q(nm):
    """詩名→原文搜查詢詞：取詩題（如『菊花詩·憶菊』→『憶菊』；『判詞（香菱）…』→『根并荷花』）。"""
    t = nm.split("｜")[0].split("（")[0]
    for sep in ("·", "／", "「"):
        if sep in t: t = t.split(sep)[-1]
    return t.strip()[:6] or "紅樓夢"

