def poems_body():
    """詩詞總覽：逐回列出詩詞（正詩全文顯示＋解讀），接入生態鏈。"""
    rows=[]; tot=0; raw_all=0
    for n, up, low, act in CH:
        items = POEM_DATA.get(str(n)) or []
        if not items: continue
        raw=[x for x in items if "｜原詩" in x[0]]
        san=[x for x in items if "｜原詩" not in x[0]]
        tot+=len(items); raw_all+=len(raw)
        def _li(nm, tx):
            title = esc(nm.split("｜")[0][:80])
            israw = "｜原詩" in nm
            tag = '<span class="tag">原詩</span>' if israw else '<span class="tag">解讀</span>'
            body = tx or ""
            body = re.sub(r'^原詩[:：]', '', body)
            body = body.split('　【解讀待補')[0]
            if len(body) > 900: body = body[:900] + "…"
            # 原詩：保留 HTML 標籤（esc 只對純文本），居中大字
            # 解讀：允許 <b> 等標籤，獨立註解區
            # 從標題抽出「」內之詩句，作 poemtext；解讀入 poemnote
            raw_name = nm.split("｜")[0]
            mq = re.search(r'「(.+?)」', raw_name)
            verse = mq.group(1) if mq else ''
            head = raw_name[:mq.start()] if mq else raw_name
            body_html = body.strip()
            body_html = re.sub(r'<(?!b>|/b>|br\\s*/?|em>|/em>)[^>]*>', '', body_html)
            # 標籤與原文搜移到題目右側同一行
            parts = [f'<div class="poemhead"><span class="poemtitle">{esc(head.strip()[:80])}</span>'
                     f'<span class="poemmeta">{tag}<a class="s" href="yuanwen.html?q={esc(poem_q(nm))}">原文搜</a></span></div>']
            if verse:
                # 格律字表：每句拆單字·等寬對齊
                v = esc(verse)
                v = re.sub(r'([，。？！；])', r'\1\n', v)
                vlines = [x.strip() for x in v.split('\n') if x.strip()]
                cells = []
                # 兩句一行（每聯一行）
                for i in range(0, len(vlines), 2):
                    grp = vlines[i:i+2]
                    row = ''
                    for ln in grp:
                        for c in ln:
                            row += f'<i>{c}</i>' if c not in '，。？！；' else f'<i class="pn">{c}</i>'
                        row += '<b class="pgap"></b>'
                    cells.append(f'<span class="pline">{row}</span>')
                verse_html = ''.join(cells)
                parts.append(f'<div class="poemtext grid">{verse_html}</div>')
            if body_html:
                # 自動分段：關鍵標記前插換行
                for kw in ['核心觀點','逐句','★','脂批路標','解碼軌','敘事前因後果','⚠️定案','⚠️更正']:
                    body_html = body_html.replace(kw, '<br><br>' + kw, 1)
                body_html = body_html.lstrip('<br>')
                parts.append(f'<div class="poemnote">{body_html}</div>')
            return '<li>' + ''.join(parts) + '</li>'
        lis="".join(_li(nm, tx) for nm, tx in items)
        rows.append(f'<section><h2><a href="chapters/{n:03d}.html">第{n}回</a>　{esc(up)}</h2>'
                    f'<p class="dim">詩詞 {len(items)} 條（原詩 {len(raw)} · 解讀 {len(san)}）</p>'
                    f'<ul class="poems">{lis}</ul></section>')
    return (f'<h1>詩詞總覽</h1>' + eco_nav("詩詞總覽")
            + f'<p class="lead">全書詩詞曲戲：<b>{tot} 條</b>（其中<b>原詩 {raw_all} 首</b>取自抄本原文，'
              f'標「原詩」；標「解讀」為三足解讀條目）。<b>各條正文直接顯示</b>，可點回目或「原文搜」核對抄本。</p>'
            + "".join(rows))

