YUANWEN_JS = """
(function(){
  var data=null,loading=false,pending=null;
  var inp=document.getElementById('ywQ'),out=document.getElementById('ywOut');
  if(!inp)return;
  function esc(t){return String(t).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
  function load(cb){
    if(data){cb();return;}
    if(loading){pending=cb;return;}
    loading=true;out.innerHTML='<p class="dim">首次載入抄本原文（約 2.6MB）…</p>';
    var sc=document.createElement('script');sc.src='yuanwen.js';
    sc.onload=function(){data=window.YW;loading=false;cb();if(pending){var f=pending;pending=null;f();}};
    sc.onerror=function(){out.innerHTML='<p class="dim">載入失敗，請重新整理再試。</p>';loading=false;};
    document.head.appendChild(sc);
  }
  function run(){
    var q=(inp.value||'').trim();
    if(!q){out.innerHTML='';return;}
    load(function(){
      var hits=[],total=0;
      for(var k in data){
        var t=data[k],i=t.indexOf(q);
        if(i<0)continue;
        var n=0,sn=[];
        while(i>=0&&n<5){
          sn.push('…'+esc(t.substring(Math.max(0,i-26),i))+'<mark>'+esc(t.substr(i,q.length))+'</mark>'+esc(t.substring(i+q.length,i+q.length+26))+'…');
          n++;total++;i=t.indexOf(q,i+q.length);
        }
        hits.push([parseInt(k,10),n,sn]);
      }
      hits.sort(function(a,b){return a[0]-b[0];});
      if(!hits.length){out.innerHTML='<p class="dim">原文中找不到「'+esc(q)+'」。本站原文為混合底本轉錄，通行本用字或異（如風→⻛、長→⻓）。</p>';return;}
      var h='<p class="lead">「<b>'+esc(q)+'</b>」見於 <b>'+hits.length+'</b> 回，共 <b>'+total+'</b> 處：</p>';
      hits.forEach(function(it){
        var nn=('00'+it[0]).slice(-3);
        h+='<section><h2><a href="chapters/'+nn+'.html">第'+it[0]+'回</a>　<span class="dim">'+it[1]+' 處</span></h2><ul class="plain">';
        it[2].forEach(function(x){h+='<li>'+x+'</li>';});
        h+='</ul></section>';
      });
      out.innerHTML=h;
    });
  }
  inp.addEventListener('input',run);
  // 支援 URL 參數 ?q=字（字考/詩詞等頁可深連結）
  var qp=new URLSearchParams(location.search).get('q');
  if(qp){inp.value=qp;run();}
})();
"""

def yuanwen_js():
    """原文全文檢索資料（延遲載入）：window.YW = {回: 原文}。"""
    import json as _j
    ks = sorted([k for k in YUANWEN_DATA if k.isdigit()], key=int)
    return "window.YW=" + _j.dumps({k: YUANWEN_DATA[k] for k in ks}, ensure_ascii=False, separators=(",", ":")) + ";\n"

def sitemap_xml():
    """生成 sitemap.xml：站點全部頁面（根頁＋副頁＋120 回卡），保持與生成頁同步。"""
    import datetime
    today = datetime.date.today().isoformat()
    urls = ["404.html", "index.html", "framework.html", "characters.html", "mapping.html",
            "pingyu.html", "shixi.html", "qa.html", "liuyan.html", "zikao.html", "poems.html", "yuanwen.html", "xiezi.html", "caoxue.html", "duodi.html", "daijie.html", "nianbiao.html", "jilu.html", "jinghua.html", "funding.html"]
    urls += [f"chapters/{n:03d}.html" for n in range(1, 121)]
    items = "\n".join(
        f'  <url><loc>https://judickzhu.github.io/guhai-honglou/{u}</loc><lastmod>{today}</lastmod></url>'
        for u in urls)
    return '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' + items + '\n</urlset>\n'

def liuyan_body():
    """留言區：GitHub Issues 為入口，集思優化、改進解讀正確性。"""
    return '''<h1>留言區 · 集思優化</h1>
''' + eco_nav("留言區") + '''
<section><p class="lead">本站解讀為<b>提問者個人讀法</b>——或顛覆通識本／紅學定論，<b>非權威共識</b>。歡迎各方讀者留言：提出更正、補充證據、指正斷章取義，集思優化，改進解讀正確性。</p></section>
<section><h2>留言方式（GitHub Issues）</h2>
<p>點此開一個 Issue 留言（建議先登入 GitHub 帳號；無需本站帳號）：</p>
<p class="cta"><a class="card" href="https://github.com/judickzhu/guhai-honglou/issues/new?title=留言區意見：&amp;body=%E3%80%90%E5%AF%BE%E6%87%89%E5%9B%9E%E7%9B%AE%EF%BC%8F%E4%B8%BB%E9%A1%8C%E3%80%91%0A%0A%E3%80%90%E6%84%8F%E8%A6%8B%EF%BC%8F%E6%9B%B4%E6%AD%A3%EF%BC%8F%E8%A3%9C%E5%85%85%E8%AD%89%E6%93%9A%E3%80%91%0A%0A%E3%80%90%E4%BE%9D%E6%93%9A%E3%80%91%0A-%E6%96%87%E6%9C%AC%EF%BC%9A%0A-%E8%84%82%E6%89%B9%EF%BC%9A%0A-%E5%8F%B2%E5%AF%A6%EF%BC%9A%0A-%E8%A1%8C%E8%99%9F%EF%BC%9A"><b>✍️ 開 Issue 留言</b></a></p>
<ul class="plain">
<li><b>為咗改進解讀正確性，留言請附依據</b>：抄本原文（甲戌／庚辰／蒙府／程乙）／脂批原文／史料出處與行號——站規「核對須以全文脈絡為據，不以孤立截句作證」，避免斷章取義。</li>
<li>指正範圍：任何回卡、判詞、十二支曲、字音字形解碼、成書與流傳。</li>
<li>留言由站主審閱：<b>合則入卡（標註來源），不合則存檔不採納</b>——公開、可核對。</li>
<li>已有回覆會集中喺 <a href="qa.html">問答區</a> 同步。</li>
</ul></section>
<section><h2>進階（可選）</h2>
<p>若想頁內直接留言（唔使跳去 GitHub）：開啟倉庫 <b>Discussions</b>（Settings → Features → Discussions）後可接入 <a href="https://giscus.app" target="_blank" rel="noopener">giscus</a>；或安裝 <a href="https://utteranc.es" target="_blank" rel="noopener">utterances</a> App（以 Issues 為評論）。兩者皆免費、無後端，需要時我可代為接入。</p></section>
'''

